    ', '["Merancang skematik dan layout PCB multi-layer menggunakan Altium Designer / KiCAD.","Mengembangkan firmware dasar untuk mikrokontroler (ESP32, STM32, Nordic Semiconductor).","Melakukan kalibrasi, pengujian sinyal analog/digital, dan karakterisasi sensor fisik (pH, Suhu, Tekanan, Emisi).","Mengimplementasikan protokol komunikasi industri seperti Modbus RTU/TCP, RS485, LoRaWAN, dan MQTT.","Bekerja sama dengan tim Software Engineer untuk memastikan integrasi hardware ke cloud telemetry berjalan tanpa kendala."]'::jsonb, '["Pendidikan minimal S1/D4 Teknik Elektro, Teknik Mekatronika, atau bidang terkait.","Pengalaman minimal 1-2 tahun dalam desain hardware/embedded system (Fresh Graduate berprestasi dipersilakan melamar).","Menguasai alat ukur laboratorium seperti Oscilloscope, Logic Analyzer, dan Power Supply Unit.","Kemampuan analisis troubleshooting masalah kelistrikan & noise interferensi sinyal yang baik.","Memiliki inisiatif tinggi, mampu bekerja independen maupun dalam tim."]'::jsonb, '["Gaji kompetitif & tunjangan kesehatan (BPJS Kesehatan & Ketenagakerjaan).","Akses ke fasilitas perlengkapan laboratorium & komponen prototyping terlengkap.","Lingkungan kerja inovatif dengan budaya kolaboratif yang mendukung pengembangan karir."]'::jsonb, 'open', 0) on conflict (id) do update set title = excluded.title, department = excluded.department, location = excluded.location, type = excluded.type, type_badge_color = excluded.type_badge_color, summary = excluded.summary, description = excluded.description, responsibilities = excluded.responsibilities, requirements = excluded.requirements, benefits = excluded.benefits, sort_order = excluded.sort_order;
